   "summary": "2026金融街论坛年会(10/19-22)组委会表示，国家金融管理部门将在论坛期间集中发布系列金融改革发展政策，设主论坛、平行论坛共21场议题及金融科技、保险、投资3场专题大会，彰显国家级政策宣传发布平台作用。",
   "decision": "论坛将释放下阶段金融监管与开放信号；招联应重点关注消金、助贷、网络营销等制度动向，提前对接合规要求。",
