   "summary": "布伦特结算价升至每桶106美元上方，WTI收涨1%报95.09美元；胡塞对沙特多地导弹无人机袭击、伊朗对霍尔木兹船只袭击大增，叠加俄乌互袭能源设施，供应恢复预期受挫。",
