   "summary": "针对印度内政部在拉达克地区'规范地名'一事，外交部发言人毛宁13日表示，中方从不承认印方单方面非法设立的所谓'拉达克中央直辖区'，坚决反对印方公布所谓'标准地名'，该行为非法无效，不能改变中印边境西段历来属于中国的客观事实。",
