   "summary": "10月11日国防部新闻发言人陈曦就赖清德所谓“双十”讲话答记者问：世界上只有一个中国，台湾是中国一部分；赖清德顽固坚持“台独”立场、渲染“大陆威胁”、妄图“以武谋独”，解放军位台岛周边常态开展演训活动，就是震慑“台独”妄动和外来干涉，维护台湾民众安全福祉。",
   "decision": "台海局势牵动区域风险偏好；招联作为金融机构需关注地缘事件对市场的瞬时冲击与流动性预案。",
