   "summary": "蒙古国近日发生草原火，9日至今不断向内蒙古边境线蔓延，截至11日晚暂未入境。内蒙古锡林郭勒盟东乌珠穆沁旗等边境一线紧急调集消防机动队伍与地方扑火队伍共2000余人，以携装巡护、以巡待扑方式堵截。",
